// UpdateSensor handles update requests.
func (h *SensorHandler) UpdateSensor(ctx context.Context, req *connect.Request[pb.UpdateSensorRequest]) (*connect.Response[pb.UpdateSensorResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity := &models.Sensor{
		FirmwareVersion:        req.Msg.GetFirmwareVersion(),
		Status:                 mappers.SensorStatusFromProto(req.Msg.GetStatus()),
		Protocol:               mappers.SensorProtocolFromProto(req.Msg.GetProtocol()),
		ReadingIntervalSeconds: req.Msg.GetReadingIntervalSeconds(),
	}
	entity.UUID = req.Msg.GetId()

	if req.Msg.GetLocation() != nil {
		lat := req.Msg.GetLocation().GetLatitude()
		lon := req.Msg.GetLocation().GetLongitude()
		entity.Latitude = &lat
		entity.Longitude = &lon
		entity.ElevationM = req.Msg.GetLocation().GetElevationM()
	}

	if req.Msg.GetMetadata() != nil {
		md, err := json.Marshal(req.Msg.GetMetadata())
		if err == nil {
			entity.Metadata = md
		}
	}

	updated, err := h.svc.UpdateSensor(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.UpdateSensorResponse{Sensor: mappers.SensorToProto(updated)}), nil
}

