// ---------------------------------------------------------------------------
// Data ingestion
// ---------------------------------------------------------------------------

// IngestReading handles single reading ingestion requests.
func (h *SensorHandler) IngestReading(ctx context.Context, req *connect.Request[pb.IngestReadingRequest]) (*connect.Response[pb.IngestReadingResponse], error) {
	h.log.Infow("msg", "IngestReading request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetSensorId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "sensor_id is required")
	}

	var ts time.Time
	if req.Msg.GetTimestamp() != nil {
		ts = req.Msg.GetTimestamp().AsTime()
	}

	quality := mappers.ReadingQualityFromProto(req.Msg.GetQuality())
	var batteryPct, signalDbm *float64
	if req.Msg.GetBatteryLevelPct() != 0 {
		b := req.Msg.GetBatteryLevelPct()
		batteryPct = &b
	}
	if req.Msg.GetSignalStrengthDbm() != 0 {
		s := req.Msg.GetSignalStrengthDbm()
		signalDbm = &s
	}

	var metadata json.RawMessage
	if req.Msg.GetMetadata() != nil {
		metadata = mappers.MetadataToJSON(req.Msg.GetMetadata())
	}

	reading, alert, err := h.svc.IngestReading(ctx, req.Msg.GetSensorId(), req.Msg.GetValue(), req.Msg.GetUnit(), ts, quality, batteryPct, signalDbm, metadata)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}

	resp := &pb.IngestReadingResponse{
		Reading: mappers.SensorReadingToProto(reading),
	}
	if alert != nil {
		resp.AlertTriggered = true
		resp.Alert = mappers.SensorAlertToProto(alert)
	}
	return connect.NewResponse(resp), nil
}

// BatchIngestReadings handles batch reading ingestion requests.
func (h *SensorHandler) BatchIngestReadings(ctx context.Context, req *connect.Request[pb.BatchIngestReadingsRequest]) (*connect.Response[pb.BatchIngestReadingsResponse], error) {
	h.log.Infow("msg", "BatchIngestReadings request", "tenant_id", p9context.TenantID(ctx), "count", len(req.Msg.GetReadings()))

	readings := make([]models.ReadingInput, 0, len(req.Msg.GetReadings()))
	for _, r := range req.Msg.GetReadings() {
		var ts time.Time
		if r.GetTimestamp() != nil {
			ts = r.GetTimestamp().AsTime()
		}
		var batteryPct, signalDbm *float64
		if r.GetBatteryLevelPct() != 0 {
			b := r.GetBatteryLevelPct()
			batteryPct = &b
		}
		if r.GetSignalStrengthDbm() != 0 {
			s := r.GetSignalStrengthDbm()
			signalDbm = &s
		}
		var metadata json.RawMessage
		if r.GetMetadata() != nil {
			metadata = mappers.MetadataToJSON(r.GetMetadata())
		}
		readings = append(readings, models.ReadingInput{
			SensorID:          r.GetSensorId(),
			Value:             r.GetValue(),
			Unit:              r.GetUnit(),
			Timestamp:         ts,
			Quality:           mappers.ReadingQualityFromProto(r.GetQuality()),
			BatteryLevelPct:   batteryPct,
			SignalStrengthDbm: signalDbm,
			Metadata:          metadata,
		})
	}

	ingestedCount, failedCount, errs, alerts, err := h.svc.BatchIngestReadings(ctx, readings)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.BatchIngestReadingsResponse{
		IngestedCount: ingestedCount,
		FailedCount:   failedCount,
		Errors:        errs,
		Alerts:        mappers.SensorAlertsToProto(alerts),
	}), nil
}

