// CalibrateSensor handles sensor calibration requests.
func (h *SensorHandler) CalibrateSensor(ctx context.Context, req *connect.Request[pb.CalibrateSensorRequest]) (*connect.Response[pb.CalibrateSensorResponse], error) {
	h.log.Infow("msg", "CalibrateSensor request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetSensorId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "sensor_id is required")
	}
	var nextCalDate *time.Time
	if req.Msg.GetNextCalibrationDate() != nil {
		t := req.Msg.GetNextCalibrationDate().AsTime()
		nextCalDate = &t
	}
	cal, err := h.svc.CalibrateSensor(ctx, req.Msg.GetSensorId(), req.Msg.GetOffset(), req.Msg.GetScaleFactor(), req.Msg.GetNotes(), nextCalDate)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.CalibrateSensorResponse{Calibration: mappers.SensorCalibrationToProto(cal)}), nil
}
